const stats = $('Get report').first().json;
const summary = String($json.output ?? '').trim();
const allowed = new Set();
const addNum = (v) => { allowed.add(String(v)); for (const k of [100, 10, 1]) allowed.add(String(Math.round(v * 100 * k) / k)); };
const walk = (v) => {
  if (Array.isArray(v)) v.forEach(walk);
  else if (v && typeof v === 'object') Object.entries(v).forEach(([k, x]) => { (String(k).match(/\d+(\.\d+)?/g) ?? []).forEach((n) => allowed.add(String(Number(n)))); walk(x); });
  else if (typeof v === 'string') (v.match(/\d+(\.\d+)?/g) ?? []).forEach((n) => allowed.add(String(Number(n))));
  else if (typeof v === 'number') addNum(v);
};
walk(stats);
const found = (summary.match(/\d+(\.\d+)?/g) ?? []).map((n) => String(Number(n)));
const unknown = [...new Set(found.filter((n) => !allowed.has(n)))];
const worst = [...(stats.anomalies ?? [])].sort((a, b) => b.error_rate - a.error_rate)[0];
return [{ json: { summary, numbers_ok: unknown.length === 0, unknown_numbers: unknown,
  top_topic: stats.unanswered_topics?.[0]?.topic ?? null, worst_hour: worst?.hour ?? null } }];
